.bento {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 28px;
  position: relative;
  overflow: hidden;
  box-shadow: var(--shadow-md);
}

/* NAME / PRICE card */
.bento.name-card {
  grid-row: span 2;
  background: linear-gradient(135deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-md);
}
.bento.name-card::after {
  content: '';
  position: absolute;
  top: 0; right: 0; width: 4px; bottom: 0;
  background: linear-gradient(180deg, var(--neon-cyan), var(--accent-blue));
}
.ticker-label { font-family: 'Fira Code', monospace; font-size: 11px; color: var(--neon-cyan); letter-spacing: .2em; text-transform: uppercase; margin-bottom: 10px; }
.stock-name {
  font-family: 'Fira Sans', sans-serif;
  font-weight: 900;
  font-size: 72px;
  line-height: 1;
  color: var(--text-bright);
  letter-spacing: -0.03em;
  margin-bottom: 8px;
}
.stock-code {
  font-family: 'Fira Code', monospace;
  font-size: 18px;
  color: var(--text-dim);
  margin-bottom: 28px;
}
.one-liner {
  font-size: 14px;
  color: var(--text-main);
  line-height: 1.7;
  padding: 16px 18px;
  background: var(--cyan-tint);
  border-left: 3px solid var(--neon-cyan);
  border-radius: 0 8px 8px 0;
  margin-bottom: 28px;
}
.price-row { display: flex; align-items: baseline; gap: 20px; flex-wrap: wrap; margin-bottom: 22px; }
.price {
  font-family: 'Fira Code', monospace;
  font-size: 56px;
  font-weight: 700;
  color: var(--text-bright);
  letter-spacing: -.02em;
}
.change {
  font-family: 'Fira Code', monospace;
  font-size: 22px;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: 6px;
}
.change.up { color: var(--bull-green); background: var(--bull-tint); border: 1px solid var(--bull-green); }
.change.down { color: var(--bear-red); background: var(--bear-tint); border: 1px solid var(--bear-red); }
.metric-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.chip {
  font-family: 'Fira Code', monospace;
  font-size: 11px;
  padding: 6px 12px;
  border: 1px solid var(--border);
  border-radius: 20px;
  color: var(--text-mid);
  background: var(--bg-tinted);
}
.chip strong { color: var(--text-bright); margin-right: 4px; }

/* SCORE GIANT card — BRUTALISM (light edition) */
.bento.score-card {
  background: var(--bg-card);
  border: 3px solid var(--text-bright);
  box-shadow: var(--shadow-brutal);
  display: flex; flex-direction: column; justify-content: space-between;
  min-height: 240px;
}
.score-label { font-family: 'Fira Code', monospace; font-size: 10px; letter-spacing: .25em; color: var(--neon-gold); text-transform: uppercase; font-weight: 700; }
.score-giant {
  font-family: 'Fira Sans', sans-serif;
  font-weight: 900;
  font-size: 160px;
  line-height: .85;
  color: var(--neon-gold);
  letter-spacing: -.06em;
  text-align: center;
  position: relative;
}
.score-giant::after {
  content: '/100';
  position: absolute; bottom: 0; right: 16%;
  font-size: 26px; color: var(--text-ghost);
  font-weight: 500;
}
.score-verdict {
  font-family: 'Fira Sans', sans-serif;
  font-weight: 700;
  font-size: 28px;
  color: var(--text-bright);
  text-align: center;
  padding-top: 12px;
  border-top: 2px solid var(--gold-tint);
}

/* SAFETY card */
.bento.safety-card {
  display: flex; align-items: center; gap: 18px;
  padding: 20px 24px;
}
.bento.safety-card.green  { background: var(--bull-tint); border-color: var(--bull-green); }
.bento.safety-card.yellow { background: var(--gold-tint); border-color: var(--neon-gold); }
.bento.safety-card.orange { background: #fed7aa; border-color: var(--warning-amber); }
.bento.safety-card.red    { background: var(--bear-tint); border-color: var(--bear-red); }
.safety-icon { font-size: 40px; line-height: 1; }
.safety-text strong { display: block; font-family: 'Fira Sans', sans-serif; font-weight: 700; color: var(--text-bright); font-size: 16px; margin-bottom: 4px; }
.safety-text span { color: var(--text-mid); font-size: 11px; line-height: 1.5; }

/* ═══════════════ SECTION HEADERS (BRUTAL) ═══════════════ */
.section-head {
  display: flex; align-items: center; gap: 16px;
  margin: 48px 0 20px;
}
.section-tag {
  font-family: 'Fira Code', monospace;
  font-size: 11px;
  font-weight: 600;
  color: var(--neon-cyan);
  letter-spacing: .2em;
  padding: 6px 12px;
  border: 1px solid var(--neon-cyan);
  border-radius: 4px;
  text-transform: uppercase;
  white-space: nowrap;
}
.section-title {
  font-family: 'Fira Sans', sans-serif;
  font-weight: 800;
  font-size: 32px;
  color: var(--text-bright);
  letter-spacing: -.02em;
}
.section-line { flex: 1; height: 1px; background: linear-gradient(90deg, var(--neon-cyan), transparent); }

/* ═══════════════ DASHBOARD 4-SECTION BENTO ═══════════════ */
.dashboard-bento {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: auto auto auto;
  gap: 14px;
}
.core-conclusion {
  grid-column: span 3;
  background: var(--cyan-tint);
  border: 1px solid var(--neon-cyan);
  border-radius: 18px;
  padding: 32px;
  position: relative;
  box-shadow: var(--shadow-md);
}
.core-conclusion::before {
  content: '"';
  position: absolute;
  top: -20px; left: 20px;
  font-family: 'Fira Sans', serif;
  font-size: 160px;
  color: rgba(8,145,178,.15);
  line-height: 1;
}
.core-conclusion .label {
  font-family: 'Fira Code', monospace;
  font-size: 11px; letter-spacing: .25em;
  color: var(--neon-cyan); text-transform: uppercase;
  margin-bottom: 14px;
  font-weight: 600;
}
.core-conclusion .text {
  font-family: 'Fira Sans', sans-serif;
  font-weight: 500;
  font-size: 24px;
  color: var(--text-bright);
  line-height: 1.6;
  position: relative;
  z-index: 1;
}

.data-cell {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 20px;
  position: relative;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
}
.data-cell .icon {
  position: absolute; top: 12px; right: 14px;
  font-size: 20px; opacity: .3;
}
.data-cell .key {
  font-family: 'Fira Code', monospace;
  font-size: 10px;
  letter-spacing: .2em;
  color: var(--neon-cyan);
  text-transform: uppercase;
  margin-bottom: 8px;
}
.data-cell .value {
  font-family: 'Fira Sans', sans-serif;
  font-size: 15px;
  color: var(--text-main);
  line-height: 1.5;
}

.battle-plan {
  grid-column: span 3;
  background: var(--gold-tint);
  border: 2px solid var(--neon-gold);
  border-radius: 14px;
  padding: 18px 28px;
  display: grid;
  grid-template-columns: auto repeat(4, 1fr);
  gap: 24px;
  align-items: center;
  box-shadow: var(--shadow-md);
}
.battle-plan .plan-label {
  font-family: 'Fira Sans', sans-serif;
  font-weight: 900;
  font-size: 18px;
  color: var(--neon-gold);
  letter-spacing: .05em;
  padding-right: 24px;
  border-right: 1px solid rgba(249,203,64,.3);
}
.plan-field .k { font-size: 10px; color: var(--text-dim); letter-spacing: .15em; text-transform: uppercase; display: block; margin-bottom: 4px; }
.plan-field .v { font-family: 'Fira Code', monospace; font-size: 15px; color: var(--text-bright); font-weight: 600; }

/* ═══════════════ THE GREAT DIVIDE · 拳击擂台 ═══════════════ */
.divide-section {
  margin-top: 60px;
  padding: 48px 40px 40px;
  background:
    radial-gradient(ellipse 70% 40% at 50% 0%, rgba(219,39,119,.05), transparent 60%),
    radial-gradient(ellipse 50% 40% at 20% 100%, rgba(5,150,105,.04), transparent 60%),
    radial-gradient(ellipse 50% 40% at 80% 100%, rgba(220,38,38,.04), transparent 60%),
    var(--bg-card);
  border: 2px solid var(--border);
  border-radius: 24px;
  position: relative;
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}
/* spotlight / projector beams */
.divide-section::after {
  content: '';
  position: absolute;
  inset: 0;
  background:
    repeating-linear-gradient(115deg, transparent, transparent 60px, rgba(6,216,216,.015) 60px, rgba(6,216,216,.015) 62px),
    repeating-linear-gradient(-115deg, transparent, transparent 60px, rgba(180,108,255,.015) 60px, rgba(180,108,255,.015) 62px);
  pointer-events: none;
  mix-blend-mode: screen;
}
.divide-section::before {
  content: 'KO · KO · KO · KO';
  position: absolute;
  top: 30%; left: 50%;
  transform: translate(-50%, -50%);
  font-family: 'Fira Sans', sans-serif;
  font-weight: 900;
  font-size: 200px;
  color: rgba(15,23,42,.025);
  letter-spacing: .12em;
  pointer-events: none;
  white-space: nowrap;
  z-index: 0;
}
.divide-header {
  text-align: center;
  margin-bottom: 40px;
  position: relative;
  z-index: 2;
}
.divide-header .tag {
  display: inline-block;
  font-family: 'Fira Code', monospace;
  font-size: 11px;
  color: var(--neon-pink);
  letter-spacing: .3em;
  padding: 4px 16px;
  border: 1px solid var(--neon-pink);

